Destino.addItem(""); // Opção vazia        String sqlBancos = "SELECT nomebco, codigo, fk_gpprinc FROM tbrecursos WHERE fk_gpprinc LIKE '1.%' ORDER BY nomebco";        try {            conexao.abrirConexao();            PreparedStatement stmt = conexao.getConexao().prepareStatement(sqlBancos);            ResultSet rs = stmt.executeQuery();            while (rs.next()) {                String item = rs.getString("nomebco") + "-" + rs.getString("codigo") + "-" + rs.getString("fk_gpprinc");                jComboBoxBancoDestino.addItem(item);            }            rs.close();            //System.out.println("Bancos carregados: " + jComboBoxBancoDestino.getItemCount() + " itens");        } catch (SQLException ex) {            JOptionPane.showMessageDialog(null, "Erro ao carregar bancos: " + ex.getMessage());            ex.printStackTrace();        } finally {            conexao.fecharConexao();        }        // === ADICIONE ISSO NO FINAL DO initComponents() ===        jComboBoxBancoDestino.addActionListener(new java.awt.event.ActionListener() {            public void actionPerformed(java.awt.event.ActionEvent evt) {                jComboBoxBancoDestinoActionPerformed(evt);            }        });        // Data e visibilidade        DateFormat dateFormat = new SimpleDateFormat("dd/MM/yyyy");        Calendar c = Calendar.getInstance();        //c.add(Calendar.DATE, -60);        tfLancto.setText(dateFormat.format(c.getTime()));        tfEmissao.setText(dateFormat.format(c.getTime()));        jLabelBancoDestino.setVisible(false);        jComboBoxBancoDestino.setVisible(false);        tfNrBancoDestino.setVisible(false);        tfBancoDestino.setVisible(false);        try {            mfData = new MaskFormatter("##/##/####");        } catch (ParseException ex) {            System.out.println("Erro na máscara");        }        // Passo 1: Pre-selecionar cbxClass com base no favorecido        cbxCl