double valorOriginal = Double.parseDouble(valorTexto);            double valor = valorOriginal;            String tipo = (String) jCbxTipo.getSelectedItem();            if ("S".equals(tipo) && valor > 0) {                valor = -valorOriginal;            }            String recurso = tfRecurso.getText().trim();            conexao.abrirConexao();            Connection con = conexao.getConexao();            String sql = "INSERT INTO tbmovimento(recurso, vrecurso, clifor, vCliFor, dtlancto, dtEmi, dtVcto, documento, classif, Descr, valor, dtApr, statusMov, Prev) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)";            // ===================================================================            // 1. CARTÃO DE CRÉDITO (2.001.003)            // ===================================================================            if (recurso.equals("2.001.003")) {                // --- 1. Lançamento a Pagar (0079) ---                try (PreparedStatement stmt = con.prepareStatement(sql)) {                    stmt.setString(1, "0079");                    stmt.setString(2, "2.001.003");                    stmt.setString(3, tfNrFav.getText());                    stmt.setString(4, tfFavorecidos.getText());                    stmt.setString(5, dataLancamentoSql);                    stmt.setString(6, dataEmissaoSql);                    stmt.setString(7, dataVencimentoSql);                    stmt.setString(8, tfDocumento.getText());                    stmt.setString(9, tfClass.getText());                    stmt.setString(10, tfDescricao.getText());                    stmt.setDouble(11, valor < 0 ? valor : -valorOriginal); // Sempre negativo                    stmt.setString(12, dataApresentacaoSql);                    stmt.setString(13, "PG");                    stmt.setString(14, "V");                    stmt.execute();                }                // --- 2. Pagamento (baixa da dívida) ---                try (PreparedStatement stmt = con.prepareStatement(sql)) {                    stmt.setString(1, "0079");                    stmt.setString(2, "2.001.003");                    stmt.setString(3, tfNrFav.getText());                    stmt.setString(4, tfFavorecidos.getText());                    stmt.setString(5, dataLancamentoSql);                    stmt.setString(6, dataEmissaoSql);                    stmt.setString(7, dataVencimentoSql);                    stmt.setString(8, tfDocumento.getText());                    stmt.setString(9, "9.001.003");                    stmt.setString(10, tfDescricao.getText());                    stmt.setDouble(11, Math.abs(valorOriginal));                    stmt.setString(12, dataApresentacaoSql);                    stmt.setString(13, "PG");                    stmt.setString(14, "V");                    stmt.execute();                }                // --- 3. Saída pelo CARTÃO ---                try (PreparedStatement stmt = con.prepareStatement(sql)) {                    stmt.setString(1, tfNrRecurso.getText());                    stmt.setString(2, "2.001.003");                    stmt.setString(3, tfNrFav.getText());                    stmt.setString(4, tfFavorecidos.getText());                    stmt.setString(5, dataLancamentoSql);                    stmt.setString(6, dataEmissaoSql);                    stmt.setString(7, dataVencimentoSql);                    stmt.setString(8, tfDocumento.getText());                    stmt.setString(9, "9.001.003");                    stmt.setString(10, tfDescricao.getText());                    stmt.setDouble(11, valor);                    stmt.setDate(12, null);                    stmt.setString(13, "");                    stmt.setString(14, "V");                    stmt.execute();                }                JOptionPane.showMessageDialog(null, "Cartão de Crédito lançado com sucesso!");            }             // ===================================================================            // 2. EMPRÉSTIMO (2.001.004 ou 2.002.001)            // ===================================================================            else if (recurso.equals("2.001.004") || recurso.equals("2.002.001")) {                double valorAbs = Math.abs(valorOriginal);                // --- 1. Entrada no Banco (Caixa) ---                try (PreparedStatement stmt = con.prepareStatement(sql)) {                    stmt.setString(1, tfNrBancoDestino.getText());                    stmt.setString(2, tfBancoDestino.getText());                    stmt.setString(3, tfNrFav.getText());                    stmt.setString(4, tfFavorecidos.getText());                    stmt.setString(5, dataLancamentoSql);                    stmt.setString(6, dataEmissaoSql);                    stmt.setString(7, dataLancamentoSql);                    stmt.setString(8, tfDocumento.getText());                    stmt.setString(9, "3.003.005");                    stmt.setString(10, "Empréstimo Obtido - " + tfDescricao.getText());                    stmt.setDouble(11, valorAbs);                    stmt.setString(12, dataLancamentoSql);                    stmt.setString(13, "RC");                    stmt.setString(14, "V");                    stmt.execute();                }                // --- 2. Passivo (0080) ---                try (PreparedStatement stmt = con.prepareStatement(sql)) {                    stmt.setString(1, "0080");                    stmt.setString(2, recurso);                    stmt.setString(3, tfNrFav.getText());                    stmt.setString(4, tfFavorecidos.getText());                    stmt.setString(5, dataLancamentoSql);                    stmt.setString(6, dataEmissaoSql);                    stmt.setString(7, dataVencimentoSql);                    stmt.setString(8, tfDocumento.getText());                    stmt.setString(9, "4.008.011");                    stmt.setString(10, "Obrigação Emprétimo - " + tfDescricao.getText());                    stmt.setDouble(11, -valorAbs);                    stmt.setString(12, dataApresentacaoSql);                    stmt.setString(13, (dataApresentacaoSql == null || dataApresentacaoSql.trim().isEmpty()) ? "" : "PG");                    stmt.setString(14, "V");                    stmt.execute();                }                // --- 3. Contas a Pagar (0079) ---                try (PreparedStatement stmt = con.prepareStatement(sql)) {                    stmt.setString(1, "0079");                    stmt.setString(2, "2.001.004");                    stmt.setString(3, tfNrFav.getText());                    stmt.setString(4, tfFavorecidos.getText());                    stmt.setString(5, dataLancamentoSql);                    stmt.setString(6, dataEmissaoSql);                    stmt.setString(7, dataVencimentoSql);                    stmt.setString(8, tfDocumento.getText());                    stmt.setString(9, "9.001.003");                    stmt.setString(10, "Empréstimo à Pagar - " + tfDescricao.getText());                    stmt.setDouble(11, -valorAbs);                    stmt.setString(12, dataApresentacaoSql);                    stmt.setString(13, dataApresentacaoSql != null ? "PG" : "");                    stmt.setString(14, "V");                    stmt.execute();                }                // --- 4. Se já foi pago (dtApr preenchida) ---                if (dataApresentacaoSql != null) {                    // Baixa da dívida (0079)                    try (PreparedStatement stmt = con.prepareStatement(sql)) {                        stmt.setString(1, "0079");                        stmt.setString(2, "2.001.005");                        stmt.setString(3, tfNrFav.getText());                        stmt.setString(4, tfFavorecidos.getText());                        stmt.setString(5, dataLancamentoSql);                        stmt.setString(6, dataEmissaoSql);                        stmt.setString(7, dataVencimentoSql);                        stmt.setString(8, tfDocumento.getText());                        stmt.setString(9, "9.001.003");                        stmt.setString(10, "Pagamento Empréstimo - " + tfDescricao.getText());                        stmt.setDouble(11, valorAbs);                        stmt.setString(12, dataApresentacaoSql);                        stmt.setString(13, "PG");                        stmt.setString(14, "V");                        stmt.execute();                    }                    // Saída do banco                    try (PreparedStatement stmt = con.prepareStatement(sql)) {                        stmt.setString(1, tfNrBancoDestino.getText());                        stmt.setString(2, tfBancoDestino.getText());                        stmt.setString(3, tfNrFav.getText());                        stmt.setString(4, tfFavorecidos.getText());                        stmt.setString(5, dataLancamentoSql);                        stmt.setString(6, dataEmissaoSql);                        stmt.setString(7, dataApresentacaoSql);                        stmt.setString(8, tfDocumento.getText());                        stmt.setString(9, "9.001.003");                        stmt.setString(10, "Saída Pagto Empréstimo - " + tfDescricao.getText());                        stmt.setDouble(11, -valorAbs);                        stmt.setString(12, dataApresentacaoSql);                        stmt.setString(13, "PG");                        stmt.setString(14, "V");                        stmt.execute();                    }                    // Baixa do Passivo                    try (PreparedStatement stmt = con.prepareStatement(sql)) {                        stmt.setString(1, "0080");                        stmt.setString(2, recurso);                        stmt.setString(3, tfNrFav.getText());                        stmt.setString(4, tfFavorecidos.getText());                        stmt.setString(5, dataLancamentoSql);                        stmt.setString(6, dataEmissaoSql);                        stmt.setString(7, dataApresentacaoSql);                        stmt.setString(8, tfDocumento.getText());                        stmt.setString(9, "9.001.003");                        stmt.setString(10, "Baixa Obrig. Empréstimo - " + tfDescricao.getText());                        stmt.setDouble(11, valorAbs);                        stmt.setString(12, dataApresentacaoSql);                        stmt.setString(13, "PG");                        stmt.setString(14, "V");                        stmt.execute();                    }                }                JOptionPane.showMessageDialog(null, "Empréstimo lançado com sucesso!");            } // ===================================================================            // 3. Lançamento SIMPLES (outros recursos)            // ===================================================================            else {                try (PreparedStatement stmt = con.prepareStatement(sql)) {                    stmt.setString(1, tfNrRecurso.getText());                    stmt.setString(2, tfRecurso.getText());                    stmt.setString(3, tfNrFav.getText());                    stmt.setString(4, tfFavorecidos.getText());                    stmt.setString(5, dataLancamentoSql);                    stmt.setString(6, dataEmissaoSql);                    stmt.setString(7, dataVencimentoSql);                    stmt.setString(8, tfDocumento.getText());                    stmt.setString(9, tfClass.getText());                    stmt.setString(10, tfDescricao.getText());                    stmt.setDouble(11, valor);                    stmt.setString(12, dataApresentacaoSql);                    stmt.setString(13, tfStatusMov.getText());                    stmt.setString(14, tfPrev.getText());                    stmt.execute();                }                JOptionPane.showMessageDialog(null, "Movimentação lançada com sucesso!");            }            // Atualiza tela e limpa campos            new Tela_Mov().show();            dispose();            JRefresh();            ListaDados();            // Limpar campos            tfRegistro.setText("");            tfNrRecurso.setText("");            tfRecurso.setText("");            tfNrFav.setText("");            tfFavorecidos.setText("");            tfLancto.setText("");            tfEmissao.setText("");            tfVencimento.setText("");            tfApresentacao.setText("");            tfDocumento.setText("");            tfClass.setText("");            tfDescricao.setText("");            tfValor.setText("");            tfStatusMov.setText("");            tfPrev.setText("");            tfNrBancoDestino.setText("");            tfBancoDestino.setText("");            jCbxTipo.setSelectedIndex(0);            cbxClass.setSelectedIndex(0);            jComboBoxBancoDestino.setSelectedIndex(0);        } catch (ParseException | SQLException ex) {            Logger.getLogger(Tela_Mov.class.getName()).log(Level.SEVERE, null, ex);            JOptionPane.showMessageDialog(null, "Erro ao salvar: " + ex.getMessage());        } finally {            conexao.fecharConexao();        }    }//GEN-LAST:event_btSalvarActionPerformed    private void jComboBoxBancoDestinoActionPerformed(java.awt.event.ActionEvent evt) {        String selected = (String) jComboBoxBancoDestino.getSelectedItem();        if (selected == null || selected.trim().isEmpty() || selected.equals("")) {            tfNrBancoDestino.setText("");            tfBancoDestino.setText("");            return;        }        try {            // Formato: "BRADESCO-0237-1.001.001"            int lastDash = selected.lastIndexOf('-');            int secondLastDash = selected.lastIndexOf('-', lastDash - 1);            String codigo = selected.substring(secondLastDash + 1, lastDash);            String vrecurso = selected.substring(lastDash + 1);            tfNrBancoDestino.setText(codigo);            tfBancoDestino.setText(vrecurso);            //System.out.println("Banco selecionado: " + codigo + " | " + vrecurso);        } catch (Exception e) {            tfNrBancoDestino.setText("");            tfBancoDestino.setText("");            System.out.println("Erro ao processar banco: " + e.getMessage());        }    }    private void btAbrirActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btAbrirActionPerformed        //SimpleDateFormat sdf = new SimpleDateFormat("dd/MM/yyyy");        if (tfBusca.getText().equals("")) {            JOptionPane.showMessageDialog(null, "Informe um código válido...");        } else {            try {                conexao.abrirConexao(); // Abre a conexão                Connection con = conexao.getConexao(); // Obtém a conexão                 String sql = "SELECT * FROM tbmovimento WHERE idMov=?";                PreparedStatement stmt = con.prepareStatement(sql);                stmt.setString(1, tfBusca.getText());                try (ResultSet rs = stmt.executeQuery()) {                    // Formatação das datas                    SimpleDateFormat formatoSaida = new SimpleDateFormat("dd/MM/yyyy");                    SimpleDateFormat formatoEntrada = new SimpleDateFormat("yyyy-MM-dd");                    while (rs.next()) {                        tfRegistro.setText(rs.getString("idMov"));                        tfNrRecurso.setText(rs.getString("recurso"));                        tfRecurso.setText(rs.getString("vrecurso"));                        selecionarItemComboBox(jComboBoxRecurso, rs.getString("recurso"));                        tfNrFav.setText(rs.getString("clifor"));                        tfFavorecidos.setText(rs.getString("vCliFor"));                        selecionarItemComboBox(jComboBoxFavorecidos, rs.getString("clifor"));                        // Convertendo as datas de lançamento, Emissao e Vencimento                        String dataLancamento = rs.getString("dtlancto");                        if (dataLancamento != null && !dataLancamento.isEmpty()) {                            try {                                // Tenta analisar como um timestamp longo                                long timestampLancamento = Long.parseLong(dataLancamento);                                java.util.Date dataLancamentoUtil = new java.util.Date(timestampLancamento);                                String dataLancamentoFormatada = formatoSaida.format(dataLancamentoUtil);                                tfLancto.setText(dataLancamentoFormatada);                            } catch (NumberFormatException e) {                                // Se falhar, tenta analisar como uma data no formato yyyy-MM-dd                                try {                                    java.util.Date dataLancamentoUtil = formatoEntrada.parse(dataLancamento);                                    String dataLancamentoFormatada = formatoSaida.format(dataLancamentoUtil);                                    tfLancto.setText(dataLancamentoFormatada);                                } catch (ParseException pe) {                                    // Lida com erro de análise                                    tfLancto.setText("Data inválida");                                }                            }                        } else {                            tfLancto.setText("");                        }                        String dataEmissao = rs.getString("dtEmi");                        if (dataEmissao != null && !dataEmissao.isEmpty()) {                            try {                                // Tenta analisar como um timestamp longo                                long timestampEmissao = Long.parseLong(dataEmissao);                                java.util.Date dataEmissaoUtil = new java.util.Date(timestampEmissao);                                String dataEmissaoFormatada = formatoSaida.format(dataEmissaoUtil);                                tfEmissao.setText(dataEmissaoFormatada);                            } catch (NumberFormatException e) {                                // Se falhar, tenta analisar como uma data no formato yyyy-MM-dd                                try {                                    java.util.Date dataEmissaoUtil = formatoEntrada.parse(dataEmissao);                                    String dataEmissaoFormatada = formatoSaida.format(dataEmissaoUtil);                                    tfEmissao.setText(dataEmissaoFormatada);                                } catch (ParseException pe) {                                    // Lida com erro de análise                                    tfEmissao.setText("Data inválida");                                }                            }                        } else {                            tfEmissao.setText("");                        }                        String dataVencimento = rs.getString("dtVcto");                        if (dataVencimento != null && !dataVencimento.isEmpty()) {                            try {                                // Tenta analisar como um timestamp longo                                long timestampVencimento = Long.parseLong(dataVencimento);                                java.util.Date dataVencimentoUtil = new java.util.Date(timestampVencimento);                                String dataVencimentoFormatada = formatoSaida.format(dataVencimentoUtil);                                tfVencimento.setText(dataVencimentoFormatada);                            } catch (NumberFormatException e) {                                // Se falhar, tenta analisar como uma data no formato yyyy-MM-dd                                try {                                    java.util.Date dataVencimentoUtil = formatoEntrada.parse(dataVencimento);                                    String dataVencimentoFormatada = formatoSaida.format(dataVencimentoUtil);                                    tfVencimento.setText(dataVencimentoFormatada);                                } catch (ParseException pe) {                                    // Lida com erro de análise                                    tfVencimento.setText("Data inválida");                                }                            }                        } else {                            tfVencimento.setText("");                        }                        tfDocumento.setText(rs.getString("documento"));                        tfClass.setText(rs.getString("classif"));                        selecionarCbxClassPorCodigo(tfClass.getText().trim());                        tfDescricao.setText(rs.getString("Descr"));                        tfValor.setText(rs.getString(String.valueOf("Valor")));                        Double ver = 0.00;                        ver = Double.valueOf(tfValor.getText().replaceAll(",", "."));                        if (ver > 0) {                            jButtonPag.setEnabled(false);                        } else {                            jButtonReceb.setEnabled(false);                        }                        String dataApresentacao = rs.getString("dtApr");                        if (dataApresentacao != null && !dataApresentacao.isEmpty()) {                            try {                                // Tenta analisar como um timestamp longo                                long timestampApresentacao = Long.parseLong(dataApresentacao);                                java.util.Date dataApresentacaoUtil = new java.util.Date(timestampApresentacao);                                String dataApresentacaoFormatada = formatoSaida.format(dataApresentacaoUtil);                                tfApresentacao.setText(dataApresentacaoFormatada);                            } catch (NumberFormatException e) {                                // Se falhar, tenta analisar como uma data no formato yyyy-MM-dd                                try {                                    java.util.Date dataApresentacaoUtil = formatoEntrada.parse(dataApresentacao);                                    String dataApresentacaoFormatada = formatoSaida.format(dataApresentacaoUtil);                                    tfApresentacao.setText(dataApresentacaoFormatada);                                } catch (ParseException pe) {                                    // Lida com erro de análise                                    tfApresentacao.setText("Data inválida");                                }                            }                        } else {                            tfApresentacao.setText("");                        }                        tfStatusMov.setText(rs.getString("statusMov"));                        tfPrev.setText(rs.getString("Prev"));                        btSalvar.setEnabled(false);                    }                }            } catch (SQLException ex) {                Logger.getLogger(Tela_Mov.class                        .getName()).log(Level.SEVERE, null, ex);            } finally {                conexao.fecharConexao(); // Fecha a conexão no final            }        }    }//GEN-LAST:event_btAbrirActionPerformed    private void btnListarDadosActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnListarDadosActionPerformed        try {            ListaDados();        } catch (ParseException ex) {            Logger.getLogger(Tela_Mov.class.getName()).log(Level.SEVERE, null, ex);        }    }//GEN-LAST:event_btnListarDadosActionPerformed    private void btnAtualizarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnAtualizarActionPerformed        String t = "S";        try {            // TODO add your handling code here:            conexao.abrirConexao(); // Abre a conexão            Connection con = conexao.getConexao(); // Obtém a conexão            SimpleDateFormat formatoEntrada = new SimpleDateFormat("dd/MM/yyyy");            SimpleDateFormat formatoSaida = new SimpleDateFormat("yyyy-MM-dd");            String sql = "UPDATE tbmovimento SET recurso=?,vrecurso=?,clifor=?,vclifor=?,dtlancto=?,dtEmi=?,dtVcto=?,documento=?,classif=?,Descr=?,valor=?,dtApr=?,statusMov=?,Prev=? WHERE idMov=?";            PreparedStatement stmt = con.prepareStatement(sql);            stmt.setString(1, (String) tfNrRecurso.getText());            stmt.setString(2, (String) tfRecurso.getText());            stmt.setString(3, tfNrFav.getText());            stmt.setString(4, tfFavorecidos.getText());            String dataLancamentoTexto = tfLancto.getText();            java.util.Date dataLancamentoUtil = formatoEntrada.parse(dataLancamentoTexto);            String dataLancamentoSql = formatoSaida.format(dataLancamentoUtil);            stmt.setString(5, dataLancamentoSql);            String dataEmissaoTexto = tfEmissao.getText();            java.util.Date dataEmissaoUtil = formatoEntrada.parse(dataEmissaoTexto);            String dataEmissaoSql = formatoSaida.format(dataEmissaoUtil);            stmt.setString(6, dataEmissaoSql);            String dataVencimentoTexto = tfVencimento.getText();            java.util.Date dataVencimentoUtil = formatoEntrada.parse(dataVencimentoTexto);            String dataVencimentoSql = formatoSaida.format(dataVencimentoUtil);            stmt.setString(7, dataVencimentoSql);            stmt.setString(8, tfDocumento.getText());            stmt.setString(9, tfClass.getText());            stmt.setString(10, tfDescricao.getText());            // Remover todos os pontos, exceto o decimal e mantendo o sinal negativo            //String valorTexto = tfValor.getText().replaceAll("\\.", "");            String valorTexto = tfValor.getText().replaceAll("[^\\d,\\-]", "");            // Substituir a vírgula decimal por ponto decimal            valorTexto = valorTexto.replaceAll(",", ".");            // Parse para Double            stmt.setDouble(11, Double.parseDouble(valorTexto));            //stmt.setDouble(11, Double.parseDouble(tfValor.getText().replaceAll(",", ".")));            if (tfApresentacao.getText().isEmpty()) {                stmt.setDate(12, null);            } else if (tfApresentacao.getText().equals("  /  /    ")) {                tfApresentacao.setValue(null);                stmt.setDate(12, null);            } else {                String dataApresentacaoTexto = tfApresentacao.getText();                java.util.Date dataApresentacaoUtil = formatoEntrada.parse(dataApresentacaoTexto);                String dataApresentacaoSql = formatoSaida.format(dataApresentacaoUtil);                stmt.setString(12, dataApresentacaoSql);            }            stmt.setString(13, tfStatusMov.getText());            stmt.setString(14, tfPrev.getText());            stmt.setString(15, tfRegistro.getText());            stmt.execute();            DefaultTableModel modelo = (DefaultTableModel) tbDadosMov.getModel();            modelo.setRowCount(0);            stmt.close();            con.close();            JOptionPane.showMessageDialog(null, "Movimento atualizado com sucesso!");            btSalvar.setEnabled(true);            tfRegistro.setText("");            //tfNrRecurso.setText("");            //tfRecurso.setText("");            tfNrFav.setText("");            tfFavorecidos.setText("");            //tfLancto.setText("");            tfEmissao.setText("");            tfVencimento.setText("");            tfDocumento.setText("");            tfClass.setText("");            tfDescricao.setText("");            tfValor.setText("");            tfApresentacao.setText("");            tfStatusMov.setText("");            tfPrev.setText("");            //jCbxTipo.setSelectedIndex(0);            cbxClass.setSelectedIndex(0);            tfBusca.setText("");            //ListaDados();            JRefresh();        } catch (SQLException | ParseException ex) {            Logger.getLogger(Tela_Mov.class                    .getName()).log(Level.SEVERE, null, ex);        } finally {            conexao.fecharConexao(); // Fecha a conexão no final        }    }//GEN-LAST:event_btnAtualizarActionPerformed    @SuppressWarnings("deprecation")    private void btnExcluirActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnExcluirActionPerformed        int[] rows = tbDadosMov.getSelectedRows();        int rowCount = rows.length;        Object[] options = {"Sim", "Não"};        String message;        if (rowCount > 1) {            message = "Deseja excluir os " + rowCount + " registros selecionados?";        } else if (rowCount == 1 || !tfRegistro.getText().equals("")) {            message = "Deseja Excluir o Registro?";        } else {            JOptionPane.showMessageDialog(null, "Selecione ao menos um registro para excluir.");            return;        }        int i = JOptionPane.showOptionDialog(null, message, "Exclusão", JOptionPane.YES_NO_OPTION, JOptionPane.QUESTION_MESSAGE, null, options, options[0]);        if (i == JOptionPane.YES_OPTION) {            try {                conexao.abrirConexao();                Connection con = conexao.getConexao();                String sql = "DELETE FROM tbmovimento WHERE idMov=?";                PreparedStatement stmt = con.prepareStatement(sql);                if (rowCount > 0) {                    for (int row : rows) {                        // Obtém o ID da coluna 0 (idMov)                        Object idValue = tbDadosMov.getValueAt(row, 0);                        if (idValue != null) {                            stmt.setString(1, idValue.toString());                            stmt.addBatch();                        }                    }                    stmt.executeBatch();                } else {                    stmt.setString(1, tfRegistro.getText());                    stmt.execute();                }                stmt.close();                con.close();                if (rowCount > 1) {                    JOptionPane.showMessageDialog(null, rowCount + " movimentos excluídos com sucesso!");                } else {                    JOptionPane.showMessageDialog(null, "Movimento excluído com sucesso!");                }                // Limpando os dados e atualizando                tfRegistro.setText("");                tfNrFav.setText("");                tfFavorecidos.setText("");                tfLancto.setText("");                tfEmissao.setText("");                tfApresentacao.setText("");                tfDocumento.setText("");                tfClass.setText("");                tfDescricao.setText("");                tfValor.setText("");                tfStatusMov.setText("");                tfPrev.setText("");                cbxClass.setSelectedIndex(0);                tfBusca.setText("");                JRefresh();            } catch (SQLException ex) {                Logger.getLogger(Tela_Mov.class.getName()).log(Level.SEVERE, null, ex);                JOptionPane.showMessageDialog(null, "Erro ao excluir registros: " + ex.getMessage());            } finally {                conexao.fecharConexao();            }        }    }//GEN-LAST:event_btnExcluirActionPerformed    private void btnFecharActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnFecharActionPerformed    